# Surah Al-Ma'ida (chapter 5) — part 1: ayat 1-10 (IDs 670-679)
SURAH = 5

ENTRIES = {
670: (
"بسم اللہ الرّحْمٰن الرّحِیْم — اے ایمان والو! عہدوں کی پابندی کرو — تمہارے لیے چوپایوں (مویشیوں) کا گوشت حلال کیا گیا — سوائے اس کے جو تمہیں پڑھ کر سنایا جائے — بغیر اس کے کہ تم عبادات کے احرام کی حالت میں شکار کو حلال سمجھو — بے شک اللہ جو چاہتا ہے فیصلہ کرتا ہے",
"""۱۔ سورۂ المائدہ کا مرکزی موضوع — عہد کی پابندی اور حلال و حرام کے واضح احکام۔
۲۔ ’’يَا أَيُّهَا الَّذِينَ آمَنُوا أَوْفُوا بِالْعُقُودِ‘‘ — اے ایمان والو! عہدوں کی پابندی کرو — یعنی ہر عہد، معاہدہ اور وعدے کو پورا کرو۔
۳۔ ’’أُحِلَّتْ لَكُم بَهِيمَۃُ الْأَنْعَامِ إِلَّا مَا يُتْلَىٰ عَلَيْكُمْ‘‘ — تمہارے لیے چوپایوں (مویشیوں) کا گوشت حلال کیا گیا — سوائے اس کے جو تمہیں پڑھ کر سنایا جائے — یعنی جو حرام چیزیں آگے بیان ہوں گی وہ استثنا ہیں۔
۴۔ ’’غَيْرَ مُحِلِّي الصَّيْدِ وَأَنتُمْ حُرُمٌ‘‘ — بغیر اس کے کہ تم عبادات کے احرام کی حالت میں شکار کو حلال سمجھو — یعنی احرام کی حالت میں شکار حرام ہے۔
۵۔ ’’إِنَّ اللّٰہَ يَحْكُمُ مَا يُرِيدُ‘‘ — بے شک اللہ جو چاہتا ہے فیصلہ کرتا ہے — یعنی حلال و حرام کا اختیار صرف اللہ کا ہے۔
۶۔ عملی سبق: ہر عہد اور معاہدہ پوری طرح پورا کرو؛ حلال و حرام کے احکام اللہ کے دیے ہوئے ہیں۔"""
),
671: (
"اے ایمان والو! اللہ کے شعائر (نشانیاں) کو حلال نہ سمجھو — اور نہ حرمت والے مہینے کو — اور نہ ہدیہ (قربانی کے جانور) کو — اور نہ گلے میں پٹے والے (جانوروں) کو — اور نہ حرمت والے گھر کی طرف آنے والوں کو — جو اپنے رب سے فضل اور رضا کے طلبگار ہوں — اور جب تم احرام سے باہر آؤ (تو) شکار کرو — اور کسی قوم کی دشمنی تمہیں حد سے بڑھنے پر آمادہ نہ کرے — اس وجہ سے کہ انہوں نے تمہیں مسجدِ حرام سے روکا — اور بھلائی اور پرہیزگاری میں باہمی تعاون کرو — اور گناہ اور زیادتی میں باہمی تعاون نہ کرو — اور اللہ سے ڈرو — بے شک اللہ سخت عذاب دینے والا ہے",
"""۱۔ اللہ کی نشانیوں اور حرمتوں کا احترام — سب مسلمانوں پر لازم۔
۲۔ ’’يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تُحِلُّوا شَعَائِرَ اللّٰہِ‘‘ — اے ایمان والو! اللہ کے شعائر (نشانیاں) کو حلال نہ سمجھو — یعنی حج و عمرہ کی جگہوں، قربانی اور احرام کے احکام پامال نہ کرو۔
۳۔ ’’وَلَا الشَّهْرَ الْحَرَامَ وَلَا الْهَدْيَ وَلَا الْقَلَائِدَ‘‘ — اور نہ حرمت والے مہینے کو — اور نہ ہدیہ (قربانی کے جانور) کو — اور نہ گلے میں پٹے والے (جانوروں) کو — یعنی ان سب کی حرمت کی پامالی جائز نہیں۔
۴۔ ’’وَلَا آمِّينَ الْبَيْتَ الْحَرَامَ يَبْتَغُونَ فَضْلًا مِّن رَّبِّهِمْ وَرِضْوَانًا‘‘ — اور نہ حرمت والے گھر کی طرف آنے والوں کو — جو اپنے رب سے فضل اور رضا کے طلبگار ہوں — یعنی کعبہ کی طرف آنے والوں پر حملہ جائز نہیں — خواہ وہ کسی بھی مذہب کے ہوں۔
۵۔ ’’وَإِذَا حَلَلْتُمْ فَاصْطَادُوا‘‘ — اور جب تم احرام سے باہر آؤ (تو) شکار کرو — یعنی احرام ختم ہونے پر شکار کی اجازت ہے۔
۶۔ ’’وَلَا يَجْرِمَنَّكُمْ شَنَآنُ قَوْمٍ أَن صَدُّوكُمْ عَنِ الْمَسْجِدِ الْحَرَامِ أَن تَعْتَدُوا‘‘ — اور کسی قوم کی دشمنی تمہیں حد سے بڑھنے پر آمادہ نہ کرے — اس وجہ سے کہ انہوں نے تمہیں مسجدِ حرام سے روکا — یعنی مظلومیت کا بدلہ لیتے ہوئے حد سے مت بڑھو۔
۷۔ ’’وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَىٰ وَلَا تَعَاوَنُوا عَلَى الْإِثْمِ وَالْعُدْوَانِ‘‘ — اور بھلائی اور پرہیزگاری میں باہمی تعاون کرو — اور گناہ اور زیادتی میں باہمی تعاون نہ کرو — یعنی تعاون صرف نیکی اور تقویٰ میں جائز ہے۔
۸۔ ’’وَاتَّقُوا اللّٰہَ إِنَّ اللّٰہَ شَدِيدُ الْعِقَابِ‘‘ — اور اللہ سے ڈرو — بے شک اللہ سخت عذاب دینے والا ہے۔
۹۔ عملی سبق: نیکی اور تقویٰ میں تعاون کرو؛ دشمنی کے باوجود انصاف برقرار رکھو۔"""
),
672: (
"تم پر حرام کر دیے گئے: مُردار، خون، سور کا گوشت، اور وہ (جانور) جس پر اللہ کے سوا کا نام لیا گیا ہو، اور گلا گھٹ کر مرا ہوا، چوٹ کھا کر مرا ہوا، اوپر سے گر کر مرا ہوا، سینگوں سے ٹکرا کر مرا ہوا، اور درندے نے پھاڑ کر کھایا ہوا — سوائے اس کے جسے تم نے ذبح کیا ہو — اور وہ (جانور) جو بتوں کے سامنے ذبح ہوئے ہوں — اور یہ کہ تم تیر (بتیں) سے قرعہ اندازی کرو — یہ سب فسق (گناہ) ہے — آج کے دن جن لوگوں نے کفر کیا وہ تمہارے دین سے مایوس ہو چکے ہیں — پس تم ان سے مت ڈرو — اور مجھ سے ڈرو — آج میں نے تمہارے لیے تمہارا دین مکمل کر دیا اور تم پر اپنی نعمت پوری کر دی اور تمہارے لیے اسلام کو مذہب کے طور پر پسند کیا — پس جو کوئی شدید بھوک (کی حالت) میں بے اختیاری سے مجبور ہو — (اتنا کھائے جو) گناہ کی طرف مائل نہ ہو — تو بے شک اللہ بخشش والا، مہربان ہے",
"""۱۔ حرام کھانوں کی مکمل فہرست — اور دین کی تکمیل کا اعلان۔
۲۔ ’’حُرِّمَتْ عَلَيْكُمُ الْمَيْتَۃُ وَالدَّمُ وَلَحْمُ الْخِنزِيرِ وَمَا أُهِلَّ لِغَيْرِ اللّٰہِ بِهِ‘‘ — تم پر حرام کر دیے گئے: مُردار، خون، سور کا گوشت، اور وہ (جانور) جس پر اللہ کے سوا کا نام لیا گیا ہو — یعنی ان تمام کی حرمت قطعی ہے۔
۳۔ ’’وَالْمُنْخَنِقَۃُ وَالْمَوْقُوذَۃُ وَالْمُتَرَدِّيَۃُ وَالنَّطِيحَۃُ وَمَا أَكَلَ السَّبُعُ إِلَّا مَا ذَكَّيْتُمْ‘‘ — اور گلا گھٹ کر مرا ہوا، چوٹ کھا کر مرا ہوا، اوپر سے گر کر مرا ہوا، سینگوں سے ٹکرا کر مرا ہوا، اور درندے نے پھاڑ کر کھایا ہوا — سوائے اس کے جسے تم نے ذبح کیا ہو — یعنی ذبح کرنا ہمیشہ شرط ہے۔
۴۔ ’’وَمَا ذُبِحَ عَلَى النُّصُبِ وَأَنْ تَسْتَقْسِمُوا بِالْأَزْلَامِ ذَٰلِكُمْ فِسْقٌ‘‘ — اور وہ (جانور) جو بتوں کے سامنے ذبح ہوئے ہوں — اور یہ کہ تم تیر (بتیں) سے قرعہ اندازی کرو — یہ سب فسق (گناہ) ہے — یعنی بتوں کی خاطر ذبح کرنا اور جوئے سے فیصلہ کرنا حرام ہے۔
۵۔ ’’الْيَوْمَ يَئِسَ الَّذِينَ كَفَرُوا مِن دِينِكُمْ فَلَا تَخْشَوْهُمْ وَاخْشَوْنِ‘‘ — آج کے دن جن لوگوں نے کفر کیا وہ تمہارے دین سے مایوس ہو چکے ہیں — پس تم ان سے مت ڈرو — اور مجھ سے ڈرو — یعنی کفار کی امیدیں ختم ہو چکیں؛ اب صرف اللہ کا خوف رکھو۔
۶۔ ’’الْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِي وَرَضِيتُ لَكُمُ الْإِسْلَامَ دِينًا‘‘ — آج میں نے تمہارے لیے تمہارا دین مکمل کر دیا اور تم پر اپنی نعمت پوری کر دی اور تمہارے لیے اسلام کو مذہب کے طور پر پسند کیا — اہل تشیع کے نزدیک یہ آیت غدیرِ خم کے موقع پر نازل ہوئی — جب نبی ﷺ نے حضرت علی علیہ السلام کی ولایت کا اعلان فرما کر دین کو مکمل کر دیا۔
۷۔ ’’فَمَنِ اضْطُرَّ فِي مَخْمَصَۃٍ غَيْرَ مُتَجَانِفٍ لِّإِثْمٍ فَإِنَّ اللّٰہَ غَفُورٌ رَّحِيمٌ‘‘ — پس جو کوئی شدید بھوک (کی حالت) میں بے اختیاری سے مجبور ہو — (اتنا کھائے جو) گناہ کی طرف مائل نہ ہو — تو بے شک اللہ بخشش والا، مہربان ہے — یعنی اضطرار میں بقا کے لیے ضرورت کے مطابق حلال ہے۔
۸۔ عملی سبق: حرام سے مکمل پرہیز کرو؛ دین مکمل ہے — اس پر ثابت قدم رہو۔"""
),
673: (
"آپ سے پوچھتے ہیں کہ ان کے لیے کیا حلال ہے — آپ کہیں: تمہارے لیے پاکیزہ چیزیں حلال ہیں — اور جو تم نے شکاری جانور سکھائے ہوئے ہیں — جنہیں اللہ نے تمہیں سکھایا (اس) کی وجہ سے تم نے سکھایا ہے — پس کھاؤ اس میں سے جو وہ تمہارے لیے (شکار) پکڑیں — اور اس پر اللہ کا نام لو — اور اللہ سے ڈرو — بے شک اللہ جلدی حساب لینے والا ہے",
"""۱۔ شکار کے کتے اور دوسرے شکاری جانور — سکھائے ہوئے ہوں تو ان کا پکڑا ہوا شکار حلال ہے۔
۲۔ ’’يَسْأَلُونَكَ مَاذَا أُحِلَّ لَهُمْ قُلْ أُحِلَّ لَكُمُ الطَّيِّبَاتُ‘‘ — آپ سے پوچھتے ہیں کہ ان کے لیے کیا حلال ہے — آپ کہیں: تمہارے لیے پاکیزہ چیزیں حلال ہیں — یعنی اچھی اور خالص چیزیں حلال ہیں۔
۳۔ ’’وَمَا عَلَّمْتُم مِّنَ الْجَوَارِحِ مُكَلِّبِينَ تُعَلِّمُونَهُنَّ مِمَّا عَلَّمَكُمُ اللّٰہُ‘‘ — اور جو تم نے شکاری جانور سکھائے ہوئے ہیں — جنہیں اللہ نے تمہیں سکھایا (اس) کی وجہ سے تم نے سکھایا ہے — یعنی شکاری جانوروں کو اللہ کے دیے ہوئے علم سے سکھایا گیا۔
۴۔ ’’فَكُلُوا مِمَّا أَمْسَكْنَ عَلَيْكُمْ وَاذْكُرُوا اسْمَ اللّٰہِ عَلَيْهِ‘‘ — پس کھاؤ اس میں سے جو وہ تمہارے لیے (شکار) پکڑیں — اور اس پر اللہ کا نام لو — یعنی شکار کے وقت اللہ کا نام لینا ضروری ہے۔
۵۔ ’’وَاتَّقُوا اللّٰہَ إِنَّ اللّٰہَ سَرِيعُ الْحِسَابِ‘‘ — اور اللہ سے ڈرو — بے شک اللہ جلدی حساب لینے والا ہے۔
۶۔ عملی سبق: حلال کھانے میں احتیاط کرو؛ شکار پر اللہ کا نام لینا ضروری ہے۔"""
),
674: (
"آج تمہارے لیے پاکیزہ چیزیں حلال کر دی گئیں — اور جن لوگوں کو کتاب دی گئی ان کا کھانا تمہارے لیے حلال ہے — اور تمہارا کھانا ان کے لیے حلال ہے — اور حلال ہیں اہلِ ایمان کی پاکدامن عورتیں اور جن لوگوں کو تم سے پہلے کتاب دی گئی ان کی پاکدامن عورتیں — جب تم انہیں ان کا مہر (اجر) دو — عزت (خاندان والے) چاہتے ہوئے — بدکار نہیں اور نہ خفیہ یار بنانے والے — اور جو کوئی ایمان کا انکار کرے — اس کا عمل ضائع ہو گیا — اور وہ آخرت میں نقصان اٹھانے والوں میں سے ہوگا",
"""۱۔ آج کا اعلان — حلال کھانے، اہلِ کتاب کا کھانا اور پاکدامن عورت سے نکاح۔
۲۔ ’’الْيَوْمَ أُحِلَّ لَكُمُ الطَّيِّبَاتُ‘‘ — آج تمہارے لیے پاکیزہ چیزیں حلال کر دی گئیں۔
۳۔ ’’وَطَعَامُ الَّذِينَ أُوتُوا الْكِتَابَ حِلٌّ لَّكُمْ وَطَعَامُكُمْ حِلٌّ لَّهُمْ‘‘ — اور جن لوگوں کو کتاب دی گئی ان کا کھانا تمہارے لیے حلال ہے — اور تمہارا کھانا ان کے لیے حلال ہے — یعنی اہلِ کتاب کا حلال ذبیحہ کھانا جائز ہے۔
۴۔ ’’وَالْمُحْصَنَاتُ مِنَ الْمُؤْمِنَاتِ وَالْمُحْصَنَاتُ مِنَ الَّذِينَ أُوتُوا الْكِتَابَ مِن قَبْلِكُمْ‘‘ — اور حلال ہیں اہلِ ایمان کی پاکدامن عورتیں اور جن لوگوں کو تم سے پہلے کتاب دی گئی ان کی پاکدامن عورتیں — یعنی اہلِ کتاب کی پاکدامن عورتوں سے نکاح کی اجازت۔
۵۔ ’’إِذَا آتَيْتُمُوهُنَّ أُجُورَهُنَّ مُّحْصِنِينَ غَيْرَ مُسَافِحِينَ وَلَا مُتَّخِذِي أَخْدَانٍ‘‘ — جب تم انہیں ان کا مہر (اجر) دو — عزت (خاندان والے) چاہتے ہوئے — بدکار نہیں اور نہ خفیہ یار بنانے والے — یعنی نکاح مہر کے ساتھ، پاکدامنی کے ساتھ ہو۔
۶۔ ’’وَمَن يَكْفُرْ بِالْإِيمَانِ فَقَدْ حَبِطَ عَمَلُهُ وَهُوَ فِي الْآخِرَۃِ مِنَ الْخَاسِرِينَ‘‘ — اور جو کوئی ایمان کا انکار کرے — اس کا عمل ضائع ہو گیا — اور وہ آخرت میں نقصان اٹھانے والوں میں سے ہوگا۔
۷۔ عملی سبق: حلال کھانے اور نکاح کے احکام پوری طرح جان کر عمل کرو؛ ایمان کی حفاظت کرو۔"""
),
675: (
"اے ایمان والو! جب تم نماز کے لیے کھڑے ہو تو اپنے چہرے اور اپنے ہاتھ — کہنیوں تک — دھو لو — اور اپنے سروں اور اپنے پاؤں — ٹخنوں تک — کا مسح کرو — اور اگر تم جنابت کی حالت میں ہو تو خوب پاک ہو جاؤ (غسل کرو) — اور اگر تم بیمار ہو یا سفر میں ہو یا تم میں سے کوئی بیت الخلاء سے آیا ہو یا تم نے عورتوں کو چھوا ہو (ہم بستری کی ہو) — اور پھر تمہیں پانی نہ ملے تو پاک مٹی سے تیمم کرو — اپنے چہروں اور اپنے ہاتھوں پر اس سے (مٹی) مل لو — اللہ نہیں چاہتا کہ تم پر کوئی تنگی کرے — لیکن وہ چاہتا ہے کہ تمہیں پاک کرے اور تم پر اپنی نعمت پوری کرے — شاید کہ تم شکر ادا کرو",
"""۱۔ وضو کا مکمل طریقہ — اور تیمم کا حکم۔
۲۔ ’’يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا قُمْتُمْ إِلَى الصَّلَاةِ فَاغْسِلُوا وُجُوهَكُمْ وَأَيْدِيَكُمْ إِلَى الْمَرَافِقِ‘‘ — اے ایمان والو! جب تم نماز کے لیے کھڑے ہو تو اپنے چہرے اور اپنے ہاتھ — کہنیوں تک — دھو لو۔
۳۔ ’’وَامْسَحُوا بِرُءُوسِكُمْ وَأَرْجُلَكُمْ إِلَى الْكَعْبَيْنِ‘‘ — اور اپنے سروں اور اپنے پاؤں — ٹخنوں تک — کا مسح کرو — اہل تشیع کے نزدیک پاؤں دھونا نہیں بلکہ ان پر مسح کرنا واجب ہے — یہ وضو کا حصہ ہے۔
۴۔ ’’وَإِن كُنتُمْ جُنُبًا فَاطَّهَّرُوا‘‘ — اور اگر تم جنابت کی حالت میں ہو تو خوب پاک ہو جاؤ (غسل کرو) — یعنی جنابت میں غسل واجب ہے۔
۵۔ ’’وَإِن كُنتُم مَّرْضَىٰ أَوْ عَلَىٰ سَفَرٍ أَوْ جَاءَ أَحَدٌ مِّنكُم مِّنَ الْغَائِطِ أَوْ لَامَسْتُمُ النِّسَاءَ فَلَمْ تَجِدُوا مَاءً فَتَيَمَّمُوا صَعِيدًا طَيِّبًا‘‘ — اور اگر تم بیمار ہو یا سفر میں ہو یا تم میں سے کوئی بیت الخلاء سے آیا ہو یا تم نے عورتوں کو چھوا ہو (ہم بستری کی ہو) — اور پھر تمہیں پانی نہ ملے تو پاک مٹی سے تیمم کرو — یعنی تیمم — پانی دستیاب نہ ہو تو مٹی استعمال کرو۔
۶۔ ’’فَامْسَحُوا بِوُجُوهِكُمْ وَأَيْدِيكُم مِّنْهُ‘‘ — اپنے چہروں اور اپنے ہاتھوں پر اس سے (مٹی) مل لو۔
۷۔ ’’مَا يُرِيدُ اللّٰہُ لِيَجْعَلَ عَلَيْكُم مِّنْ حَرَجٍ وَلَٰكِن يُرِيدُ لِيُطَهِّرَكُمْ وَلِيُتِمَّ نِعْمَتَهُ عَلَيْكُمْ لَعَلَّكُمْ تَشْكُرُونَ‘‘ — اللہ نہیں چاہتا کہ تم پر کوئی تنگی کرے — لیکن وہ چاہتا ہے کہ تمہیں پاک کرے اور تم پر اپنی نعمت پوری کرے — شاید کہ تم شکر ادا کرو — یعنی وضو اور تیمم دونوں آسانی کے لیے ہیں۔
۸۔ عملی سبق: ہر نماز سے پہلے وضو کرو؛ پانی نہ ہو تو تیمم کرو — نماز کبھی نہ چھوڑو۔"""
),
676: (
"اور اللہ کی نعمت تم پر یاد کرو اور اس کا عہد جس سے اس نے تم سے عہد لیا — جب تم نے کہا: ہم نے سنا اور ہم نے اطاعت کی — اور اللہ سے ڈرو — بے شک اللہ سینوں کی باتیں جانتا ہے",
"""۱۔ اللہ کی نعمت اور اس کے ساتھ لیا گیا عہد یاد رکھو۔
۲۔ ’’وَاذْكُرُوا نِعْمَتَ اللّٰہِ عَلَيْكُمْ وَمِيثَاقَهُ الَّذِي وَاثَقَكُم بِهِ إِذْ قُلْتُمْ سَمِعْنَا وَأَطَعْنَا‘‘ — اور اللہ کی نعمت تم پر یاد کرو اور اس کا عہد جس سے اس نے تم سے عہد لیا — جب تم نے کہا: ہم نے سنا اور ہم نے اطاعت کی — یعنی اسلام قبول کرتے وقت کی عہد بندی — اسے یاد رکھنا لازم ہے۔
۳۔ ’’وَاتَّقُوا اللّٰہَ إِنَّ اللّٰہَ عَلِيمٌ بِذَاتِ الصُّدُورِ‘‘ — اور اللہ سے ڈرو — بے شک اللہ سینوں کی باتیں جانتا ہے — یعنی اللہ تمہاری نیت جانتا ہے۔
۴۔ عملی سبق: اپنے ایمان کا عہد یاد رکھو؛ اللہ سے عہد پورا کرو۔"""
),
677: (
"اے ایمان والو! اللہ کے لیے قائم رہو — انصاف کی گواہی دینے والے بنو — اور کسی قوم کی دشمنی تمہیں انصاف سے دور کرنے پر آمادہ نہ کرے — انصاف کرو — (یہ) تقویٰ سے زیادہ قریب ہے — اور اللہ سے ڈرو — بے شک اللہ تمہارے اعمال سے باخبر ہے",
"""۱۔ انصاف — حتی کہ دشمن کے لیے بھی۔
۲۔ ’’يَا أَيُّهَا الَّذِينَ آمَنُوا كُونُوا قَوَّامِينَ لِلّٰہِ شُهَدَاءَ بِالْقِسْطِ‘‘ — اے ایمان والو! اللہ کے لیے قائم رہو — انصاف کی گواہی دینے والے بنو۔
۳۔ ’’وَلَا يَجْرِمَنَّكُمْ شَنَآنُ قَوْمٍ عَلَىٰ أَلَّا تَعْدِلُوا‘‘ — اور کسی قوم کی دشمنی تمہیں انصاف سے دور کرنے پر آمادہ نہ کرے — یعنی دشمن کے ساتھ بھی انصاف کرو۔
۴۔ ’’اعْدِلُوا هُوَ أَقْرَبُ لِلتَّقْوَىٰ‘‘ — انصاف کرو — (یہ) تقویٰ سے زیادہ قریب ہے — یعنی انصاف تقویٰ کا حصہ ہے۔
۵۔ ’’وَاتَّقُوا اللّٰہَ إِنَّ اللّٰہَ خَبِيرٌ بِمَا تَعْمَلُونَ‘‘ — اور اللہ سے ڈرو — بے شک اللہ تمہارے اعمال سے باخبر ہے۔
۶۔ عملی سبق: دشمن کے ساتھ بھی انصاف کرو؛ یہی تقویٰ کی اصل ہے۔"""
),
678: (
"اللہ نے — ان لوگوں سے جو ایمان لائے اور نیک اعمال کیے — وعدہ کیا ہے کہ ان کے لیے مغفرت اور بہت بڑا اجر ہے",
"""۱۔ ایمان والوں کا انعام — مغفرت اور اجر عظیم۔
۲۔ ’’وَعَدَ اللّٰہُ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُم مَّغْفِرَۃٌ وَأَجْرٌ عَظِيمٌ‘‘ — اللہ نے — ان لوگوں سے جو ایمان لائے اور نیک اعمال کیے — وعدہ کیا ہے کہ ان کے لیے مغفرت اور بہت بڑا اجر ہے — یعنی اللہ کا وعدہ حتمی ہے۔
۳۔ عملی سبق: ایمان اور نیک عمل اختیار کرو؛ اللہ کا وعدہ سچا ہے۔"""
),
679: (
"اور جو لوگ کفر کیا اور ہماری آیات جھٹلائیں — یہی آگ والے ہیں",
"""۱۔ کفار کا انجام — جہنم۔
۲۔ ’’وَالَّذِينَ كَفَرُوا وَكَذَّبُوا بِآيَاتِنَا أُولَٰئِكَ أَصْحَابُ الْجَحِيمِ‘‘ — اور جو لوگ کفر کیا اور ہماری آیات جھٹلائیں — یہی آگ والے ہیں — یعنی کفر اور تکذیب کا انجام جہنم ہے۔
۳۔ عملی سبق: اللہ کی آیات کو جھٹلاؤ مت؛ ایمان اور تقویٰ اختیار کرو۔"""
),
}
